/**
 * The fixture loader, shared by every suite that needs a signed message.
 *
 * Everything under `app/tests/fixtures/` is GENERATED by `tools/make-fixtures.mjs` — synthetic
 * messages in reserved example domains, signed by keys made on the spot. Nothing real is in
 * there and nothing real may be put there: Stamped is a tool for leaked mail, and a committed
 * message could burn a source.
 *
 * The key store is filled from the DIRECTORY LISTING, because each file is named after the DNS
 * name a verifier asks for (`<selector>._domainkey.<domain>.pub.pem`). So there is no manifest
 * to keep in sync, and the fixture that must come back `no key` gets that answer by the absence
 * of a file rather than by a flag somebody could forget to pass.
 */

import { existsSync, readdirSync, readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';

import { KeyStore, recordFromPem } from '@stamped/core';

const FIXTURE_REL = join('app', 'tests', 'fixtures');
const PROBE_REL = join(FIXTURE_REL, 'confirmed.eml');

/**
 * The repo root, found by walking up from the working directory until the fixtures are there.
 *
 * Not derived from `import.meta.url`: this suite is BUNDLED into `app/dist/test.gjs.mjs`, so that
 * URL names the bundle rather than this file, and a path built from it points at the wrong tree.
 */
function repoRoot(): string {
    let dir = process.cwd();
    for (let i = 0; i < 8; i++) {
        if (existsSync(join(dir, PROBE_REL))) return dir;
        const up = dirname(dir);
        if (up === dir) break;
        dir = up;
    }
    throw new Error(
        `${PROBE_REL} not found above ${process.cwd()} — run the suite inside the checkout, and run \`node tools/make-fixtures.mjs\` if the fixtures are missing`,
    );
}

/** One fixture as raw bytes. Bytes, because the body hash is a hash of octets. */
export function fixture(name: string): Uint8Array {
    return new Uint8Array(readFileSync(join(repoRoot(), FIXTURE_REL, name)));
}

/** The PATH of a fixture, for the suites that hand a path to a reader instead of bytes. */
export function fixturePath(...parts: string[]): string {
    return join(repoRoot(), FIXTURE_REL, ...parts);
}

/**
 * One archive fixture's path. Written by `tools/make-archive-fixtures.mjs`, which is a separate
 * generator from the signing one — these carry no signature and are byte-stable across runs.
 */
export function archive(...parts: string[]): string {
    return fixturePath('archives', ...parts);
}

/**
 * A store holding every published fixture key, as if the operator had supplied them all.
 *
 * `'operator'` and not `'archive'`: the `archive-key` caveat would then be on every fixture and
 * the caveat assertions would stop saying anything. One suite covers the archive provenance on
 * its own.
 */
export function fixtureKeys(source: 'operator' | 'archive' = 'operator'): KeyStore {
    const dir = join(repoRoot(), FIXTURE_REL, 'keys');
    const keys = new KeyStore();
    for (const file of readdirSync(dir).sort()) {
        if (!file.endsWith('.pub.pem')) continue;
        const name = file.slice(0, -'.pub.pem'.length);
        keys.add(name, recordFromPem(readFileSync(join(dir, file), 'utf8')), source);
    }
    return keys;
}
